  "12345-6789",  // ZIP+4
  "00000",       // format only, not a real-ZIP check
];

const invalid = [
  "",            // empty
  "1234",        // too short
  "123456",      // too long
  "12345-",      // dangling hyphen
  "12345-678",   // short +4
  "12345-67890", // long +4
  "123456789",   // no hyphen
  "12345 6789",  // space instead of hyphen
  " 12345",      // leading space
  "12345\n",     // trailing newline
  "1234a",       // non-digit
  "١٢٣٤٥",       // Arabic-Indic digits
];

for (const s of valid) {
  assert.ok(zipRe.test(s), `expected valid: ${JSON.stringify(s)}`);
}
for (const s of invalid) {
  assert.ok(!zipRe.test(s), `expected invalid: ${JSON.stringify(s)}`);
}

console.log(`ok: ${valid.length} valid, ${invalid.length} invalid`);
```

